fields.InputDefinition:
{
  "goal": "Open the 'Members' entity grid in Data Explorer. The reliable way: type 'Members' in the LEFT sidebar 'Search entities...' box and click the EXACT 'Members' match (not 'Board Members'/'Memberships'/etc.); if that is giving you trouble, navigate directly to http://localhost:4200/app/data-explorer/Data?entity=Members. Wait patiently if the grid is slow to load (10-30s in this resource-constrained environment). Then click a column header (e.g. Last Name) to sort the grid by that column. Success is reached when the column shows a sort indicator and the row order visibly changes to reflect the sort.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
